def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = []
        for r in rows:
            val = r[i]
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                col_values.append(val)
        if col_values:
            totals.append(sum(col_values))
        else:
            totals.append("")
    return totals

